	if err != nil {
		return "", fmt.Errorf("resolve %s: %w", worktreeRoot, err)
	}
	rel, err := filepath.Rel(base, p)
	if err != nil || rel == "." || paths.IsRelativeTraversal(rel) {
		return "", fmt.Errorf("%q is not inside %q", p, worktreeRoot)
	}
	return filepath.ToSlash(rel), nil
}

